CREATE TABLE plots (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, farm_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, area_hectares DECIMAL(15,2) NOT NULL, soil_type VARCHAR(100) NULL, status ENUM('available','cultivated','fallow','inactive') NOT NULL DEFAULT 'available', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_plots_farm_name (farm_id,name), CONSTRAINT chk_plots_area CHECK (area_hectares > 0), CONSTRAINT fk_plots_farm FOREIGN KEY (farm_id) REFERENCES farms(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
